test("classic summary scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "terms-C", "3");
  await ui.setSetting(pg_uma, "proof-threshold", "1.00");
  await ui.setSetting(pg_uma, "perm-void", "steward");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  await ui.setSetting(pg_uma, "proof-threshold-B", "0.50");
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "0.40", "note": ""})).toBe(true);
  await ui.setSetting(pg_uma, "pot", "33.33");
  await ui.setSetting(pg_uma, "alert-threshold", "3.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33", "from": "2026-03-01"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "tags": "c"}));
  expect(await ui.ratePreview(pg_uma, "A", "5.00")).toEqual({ count: 0, diff: "0.00" });
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "3.33", "tags": "a, B"}));
  expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
  expect(await ui.importPeople(pg_uma, "Ben,C")).toMatchObject({"added": 0, "updated": 1});
  expect(await ui.inlineGrade(pg_uma, p_ada, "A")).toBe(true);
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  await ui.setToday(pg_uma, "2026-04-19");
  await ui.refresh(pg_uma);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimAction(pg_vic, c_ben_0, "settle")).toBe(false);
  expect(await ui.addClaim(pg_vic, p_ben, {"amount": "7.77", "date": "2026-02-25", "note": "n", "ref": " r-1 "})).toBeNull();
  expect(await ui.quickAdd(pg_vic, {"name": "Dot", "amount": "25.00"})).toBeNull();
  expect(await ui.claimFromTemplate(pg_vic, p_cam, "T1")).toBeNull();
  expect(await ui.addPatron(pg_vic, p_ada, "Ben")).toBe(false);
  expect(await ui.search(pg_vic, "a")).toEqual([`${sheet} Ada 0.00`, `${sheet} Cam 0.00`]);
  expect(await ui.claimAction(pg_vic, c_ben_0, "void")).toBe(false);
  await ui.refresh(pg_vic);
  expect(await ui.setRate(pg_vic, {"grade": "C", "pct": "20.00"})).toBe(false);
  expect(await ui.quickAdd(pg_vic, {"name": "Ada", "amount": "1.00"})).toBeNull();
  expect(await ui.setSettingTry(pg_vic, "entry-date", "2026-03-01")).toBe(false);
  expect(await ui.addClaim(pg_vic, p_cam, {"amount": "10.35", "date": "2026-02-10", "note": "n", "ref": " r-1 "})).toBeNull();
  expect(await ui.claimAction(pg_vic, c_ben_0, "settle")).toBe(false);

